def transform(grid):
    h, w = len(grid), len(grid[0])

    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in ones)
    r1 = max(r for r, c in ones)
    c0 = min(c for r, c in ones)
    c1 = max(c for r, c in ones)
    ih, iw = r1 - r0 + 1, c1 - c0 + 1

    outside = {}
    inside = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0 or v == 1:
                continue
            if r0 <= r <= r1 and c0 <= c <= c1:
                inside.setdefault(v, []).append((r - r0, c - c0))
            else:
                outside.setdefault(v, []).append((r, c))

    markers = {v: pts[0] for v, pts in outside.items() if len(pts) == 1}
    if len(markers) < 3:
        markers = {v: pts[0] for v, pts in inside.items() if len(pts) == 1}

    coords = list(markers.values())
    minr = min(r for r, c in coords)
    maxr = max(r for r, c in coords)
    minc = min(c for r, c in coords)
    maxc = max(c for r, c in coords)
    oh, ow = maxr - minr + 3, maxc - minc + 3
    targets = {v: (r - minr + 1, c - minc + 1)
               for v, (r, c) in markers.items()}

    transforms = [
        lambda r, c: (r, c),
        lambda r, c: (oh - 1 - r, c),
        lambda r, c: (r, ow - 1 - c),
        lambda r, c: (oh - 1 - r, ow - 1 - c),
        lambda r, c: (c, r),
        lambda r, c: (oh - 1 - c, ow - 1 - r),
        lambda r, c: (c, ow - 1 - r),
        lambda r, c: (oh - 1 - c, r),
    ]

    mapping = transforms[0]
    for f in transforms:
        if all(v in inside and len(inside[v]) == 1
               and f(*inside[v][0]) == target
               for v, target in targets.items()):
            mapping = f
            break

    out = [[1 for _ in range(ow)] for _ in range(oh)]
    for r in range(ih):
        for c in range(iw):
            rr, cc = mapping(r, c)
            if 0 <= rr < oh and 0 <= cc < ow:
                out[rr][cc] = grid[r0 + r][c0 + c]
    return out
